-- lua脚本不能直接引入java常量
local SECKILL_ACTIVITY_STOCK_PREFIX = "SECKILL:ACTIVITY:STOCK:"
local SECKILL_ORDER_NO_PREFIX = "SECKILL:ORDER:"


-- 1.1.秒杀活动id
local seckillActivityId = ARGV[1]
-- 1.2.用户id
local userId = ARGV[2]

-- 2.数据key
-- 2.1.库存key
-- ..是用来拼接字符串的
local stockKey = SECKILL_ACTIVITY_STOCK_PREFIX .. seckillActivityId
-- 2.2.订单key
local orderKey = SECKILL_ORDER_NO_PREFIX .. seckillActivityId

-- 3.脚本业务
-- 3.1.判断库存是否充足 get stockKey
-- redis.call('get', stockKey)这个获取的是字符串，无法与数字比较,要用tonumber转换成数字
if(tonumber(redis.call('get', stockKey)) <= 0) then
    -- 3.2.库存不足，返回1
    return 400
end

-- 3.2. 一人一单
-- 判断用户是否下单 SISMEMBER orderKey userId
-- SISMEMBER 判断某个值是否在 set集合中  存在返回1 不存在返回0
if(redis.call('sismember', orderKey, userId) == 1) then
    -- 3.3.存在，说明是重复下单，返回2
    return 401
end

-- 3.4.扣库存 incrby stockKey -1
redis.call('incrby', stockKey, -1)
-- 3.5.下单（保存用户）sadd orderKey userId
redis.call('sadd', orderKey, userId)

-- 3.6.返回成功标识（可根据业务需求返回，比如返回0代表成功）
return 200